import local.blackmamba.vpn.*;import org.json.*;import java.nio.file.*;import java.util.*;import static local.blackmamba.vpn.Store.*;
public class ProviderGroupsTest {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 public static void main(String[] args)throws Exception{
  String raw=Files.readString(Path.of(args[0]));JSONArray original=new JSONArray(raw);SubscriptionFormats.Result parsed=SubscriptionFormats.parse(raw,"fixture",(s,p)->null);check(parsed.skipped==0&&parsed.nodes.length()==original.length(),"Flattened groups");
  Map<String,Integer> ports=new HashMap<>();for(int i=0;i<parsed.nodes.length();i++){JSONObject n=parsed.nodes.getJSONObject(i);check(n.getString("name").equals(original.getJSONObject(i).getString("remarks")),"Group title");JSONObject config=n.getJSONObject("outbound").getJSONObject("config");check(config.getJSONArray("outbounds").toString().equals(original.getJSONObject(i).getJSONArray("outbounds").toString()),"Outbound graph changed");check(config.getJSONObject("routing").getJSONArray("balancers").toString().equals(original.getJSONObject(i).getJSONObject("routing").getJSONArray("balancers").toString()),"Fallbacks changed");check(config.getJSONObject("observatory").toString().equals(original.getJSONObject(i).getJSONObject("observatory").toString()),"Observatory changed");ports.put(n.getString("id"),24000+i);}
  String first=parsed.nodes.getJSONObject(0).getString("id");JSONObject data=obj("servers",parsed.nodes,"rules",new JSONArray(),"wifi",first,"cellular",first,"defaultTarget","direct","auto",true);Configuration.Result built=Configuration.build(data,"wifi",ports,"test-only");check(built.groups.size()==original.length(),"Missing runtime groups");Path dir=Path.of(args[1]);Files.createDirectories(dir);int index=0;for(String config:built.groups.values()){JSONObject c=new JSONObject(config);check(c.getJSONArray("inbounds").length()==1,"Provider listeners leaked");check(c.getJSONArray("inbounds").getJSONObject(0).getString("listen").equals("127.0.0.1"),"Public listener");Files.writeString(dir.resolve("group-"+(index++)+".json"),config);}Files.writeString(dir.resolve("singbox.json"),built.singbox);
  JSONObject group=parsed.nodes.getJSONObject(0);JSONArray aliases=group.getJSONArray("legacyIds");check(aliases.length()>1,"Missing upgrade aliases");String old1=aliases.getString(0),old2=aliases.getString(1);JSONObject migration=obj("servers",arr(obj("id",old1,"name",group.getString("name")+" · a","profile","fixture"),obj("id",old2,"name",group.getString("name")+" · b","profile","fixture")),"wifi",old1,"cellular",old2,"fallbackWifi",old2,"defaultTarget","server:"+old1,"rules",arr(obj("target","server:"+old2)));SubscriptionIdentity.remapGroupReferences(migration,parsed.nodes);check(migration.getString("wifi").equals(first)&&migration.getString("cellular").equals(first),"Selection upgrade");check(migration.getJSONArray("rules").getJSONObject(0).getString("target").equals("server:"+first),"Rule upgrade");System.out.println("PASS "+original.length()+" whole groups; original balancers/loopbacks/observatory; local authenticated listeners; old selection/rule migration");
 }
}
